 * @hidden N
 */
scwin.dts_PersonOnDutyList_OnLoadCompleted = async function(rowcount) {
    try {
        if (scwin.gLastJob === "삭제") {
            const msg = $c.stf.getMessageParam("MSG-A001", "삭제");
            await $c.win.alert(msg);
