/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const prev_team_jang = cmb_ChrgEmpNo1.getValue();
        const prev_team_one = cmb_EmpNo1.getValue();
        const prev_date = edt_Date.getValue();
        await $c.win.alert("저장 성공");
        // 목록 다시 조회
        await scwin.search();
        await scwin.calSearch();
        scwin.setHeader();
        cmb_ChrgEmpNo1.setValue(prev_team_jang);
        cmb_EmpNo1.setValue(prev_team_one);
        edt_Date.setValue(prev_date);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF31000.trs_Save_OnSuccess" });
    }
};

