///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_C_CodeChrgEmpNo",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_C_CodeChrgEmpNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_C_CodeEmpNo",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_C_CodeEmpNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions3 = {
        id : "sbm_dts_R_CodeChrgEmpNo",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_R_CodeChrgEmpNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions4 = {
        id : "sbm_dts_R_CodeEmpNo",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_R_CodeEmpNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn4 = await $c.sbm.executeDynamic(sbmOptions4);
    // TODO Stage2: sbmRtn4 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // alert("call");

    // 팀장콤보에 팀원 추가.(YSH, 2008/08/26)
    dts_C_CodeChrgEmpNo.setBroadcast(false);
    for (let i = 1; i <= dts_C_CodeEmpNo.getRowCount(); i++) {
        if ("" !== dts_C_CodeEmpNo.getCellData(i, 1)) {
            dts_C_CodeChrgEmpNo.insertRow();
            // alert(dts_C_CodeChrgEmpNo.CountRow);
            let crow = dts_C_CodeChrgEmpNo.getRowCount();
            dts_C_CodeChrgEmpNo.setCellData(crow, "VALUE", dts_C_CodeEmpNo.getCellData(i, 1));
            dts_C_CodeChrgEmpNo.setCellData(crow, "TEXT", dts_C_CodeEmpNo.getCellData(i, 2));
        }
    }
    dts_C_CodeChrgEmpNo.setBroadcast(true, true);
    dts_C_CodeChrgEmpNo.setRowPosition(1, 0);
    dts_R_CodeChrgEmpNo.setBroadcast(false);
    for (let i = 1; i <= dts_R_CodeEmpNo.getRowCount(); i++) {
        if ("" !== dts_R_CodeEmpNo.getCellData(i, 1)) {
            dts_R_CodeChrgEmpNo.insertRow();
            // alert(dts_C_CodeChrgEmpNo.CountRow);
            let crow = dts_R_CodeChrgEmpNo.getRowCount();
            dts_R_CodeChrgEmpNo.setCellData(crow, "VALUE", dts_R_CodeEmpNo.getCellData(i, 1));
            dts_R_CodeChrgEmpNo.setCellData(crow, "TEXT", dts_R_CodeEmpNo.getCellData(i, 2));
        }
    }
    dts_R_CodeChrgEmpNo.setBroadcast(true, true);
    dts_R_CodeChrgEmpNo.setRowPosition(1, 0);

    // 달력
    const ToDay = new Date();
    const yyyy = parseInt(ToDay.getYear(), 10);
    const yyyyNext = parseInt(ToDay.getYear(), 10) + 1;
    const mm = parseInt(ToDay.getMonth(), 10) + 1;
    let str = "";
    for (let i = yyyyNext; i >= 1998; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    // alert(str);
    cmb_YYYY.CBData = str;
    cmb_YYYY.setValue(yyyy);
    // 월
    cmb_MM.setValue($c.ut.lpad(mm, 2, "0"));
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    if (edt_Date.getValue() === "") {
        await $c.win.alert("[일자]를 입력하세요.");
        edt_Date.focus();
        return;
    }
    if (cmb_ChrgEmpNo1.getValue() === "") {
        await $c.win.alert("[팀장]을 선택하세요.");
        cmb_ChrgEmpNo1.focus();
        return;
    }
    if (cmb_EmpNo1.getValue() === "") {
        await $c.win.alert("[사원]을 선택하세요.");
        cmb_EmpNo1.focus();
        return;
    }
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/PersonOnDuty.do",
        ref : "dts_C_All",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const ChrgEmpNo = $c.cp.valueOfIndex(cmb_ChrgEmpNo2, "VALUE", cmb_ChrgEmpNo2.getSelectedIndex());
    const EmpNo = $c.cp.valueOfIndex(cmb_EmpNo2, "VALUE", cmb_EmpNo2.getSelectedIndex());
    const SDate = edt_SDate.getValue();
    const EDate = edt_EDate.getValue();
    url += "&EmpNo=" + EmpNo;
    url += "&SDate=" + SDate;
    url += "&EDate=" + EDate;
    if (js_dep_cd === "2430") {
        url += "&GDUTY=";
    } else {
        url += "&GDUTY=" + js_gduty;
    }
    url += "&MKT_ID=" + js_market;
    url += "&SCREN_ID=" + 'ULDSTF31000.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_PersonOnDutyList",
        action : "/PersonOnDuty.do",
        ref : "",
        target : "dts_PersonOnDutyList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name calSearch
 * @description cal Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calSearch = async function() {
    const YYYYMM = cmb_YYYY.getValue() + cmb_MM.getValue();
    url += "&YYYYMM=" + YYYYMM;
    if (js_dep_cd === "2430") {
        url += "&GDUTY=";
    } else {
        url += "&GDUTY=" + js_gduty;
    }
    url += "&MKT_ID=" + js_market;
    const sbmOptions = {
        id : "sbm_dts_Cal",
        action : "/PersonOnDuty.do",
        ref : "",
        target : "dts_Cal=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @param {String} GridID GridID
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function(GridID, row, colid) {
    const objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..
    if (colid === "DEL_FUNC") {
        const res = window.confirm("삭제하시겠습니까?");
        if (res) {
            scwin.gLastJob = "삭제";
            url += "&DEL_EMP_NO=" + js_emp_no;
            url += "&SEQ=" + objDataID.getCellData(row, "SEQ");
            url += "&SCREN_ID=" + 'ULDSTF31000.xml';
            url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
            const sbmOptions = {
                id : "sbm_dts_PersonOnDutyList",
                action : "/PersonOnDuty.do",
                ref : "",
                target : "dts_PersonOnDutyList=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            await scwin.search();
        }
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {void}
 * @hidden N
 */
scwin.setHeader = function() {
    const h = "DUTY_DD:string,DISCLS_DUTY_CHRG_EMP_NO:string,DISCLS_DUTY_EMP_NO:string,MKT_ID:string,SEQ:string,EMP_NO:string";
    // dts_C_All.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인
    dts_C_All.insertRow();
    dts_C_All.setCellData(1, "MKT_ID", js_market);
    dts_C_All.setCellData(1, "EMP_NO", js_emp_no);
    if (js_belngdepcd === '2400' || js_dep_cd === '2400') {
        $c.cm.setColumnProp(grd_List, "DISCLS_DUTY_CHRG_EMP_NM", "Name", "오전");
        $c.cm.setColumnProp(grd_List, "DISCLS_DUTY_EMP_NM", "Name", "오후");
        txtTL01.setValue("오전");
        txtTm01.setValue("오후");
        txtTL02.setValue("오전");
        txtTm02.setValue("오후");
    }
};

/**
 * @method
 * @name alert_error2
 * @description alert error2 처리
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alert_error2 = async function(dtsObj) {
    const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (let i = 0; i < USER_DEFINE.length; i++) {
        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        let j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) === '0') {
                // '0' 임의로 떨군 INFO 메시지
                await $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                // 기존 에러 메시지
                await $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
